WITH valid AS (SELECT id, plan, start_date, end_date, status, CONCAT_WS('-', status, plan) AS status_plan_key, CONCAT_WS('/', plan, status) AS plan_status_key FROM subscriptions WHERE end_date >= DATE '2023-04-05'), latest AS (SELECT *, RANK() OVER (PARTITION BY status ORDER BY end_date) AS row_num FROM valid QUALIFY row_num = 1), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY row_num, id) AS dedup_rank FROM latest QUALIFY dedup_rank = 1), valid_subscriptions AS (SELECT *, TRIM(status) AS clean_status, UPPER(plan) AS plan_upper FROM ranked WHERE status IN ('ACTIVE', 'EXPIRED')) SELECT DATE_TRUNC('MONTH', end_date) AS activity_month, COUNT_IF(plan = 'basic') AS basic_events, COUNT(*) AS num_rows, COUNT(*) AS row_count, COUNT(CASE WHEN status = 'EXPIRED' THEN 1 END) AS expired_count, SIZE(COLLECT_SET(status)) AS num_status, GROUPING(DATE_TRUNC('MONTH', end_date)) AS gid FROM valid_subscriptions GROUP BY ROLLUP (DATE_TRUNC('MONTH', end_date));
